candidates:
/* Every selector is scoped: this stylesheet is loaded globally by Shell. */
.sixuan-candidates.candidate-popup-boxpointer {
    -arrow-background-color: rgba(22, 27, 30, 0.94);
    -arrow-border-radius: 22px;
    -arrow-border-color: rgba(255, 255, 255, 0.14);
    -arrow-border-width: 1px;
    -arrow-rise: 0;
    -arrow-base: 0;
    -boxpointer-gap: 6px;
}

.sixuan-candidates .candidate-popup-content {
    padding: 8px;
    spacing: 8px;
    color: #E8F0EA;
    font-size: 16px;
    border-radius: 22px;
    background-color: transparent;
    border-width: 0;
    box-shadow: none;
}

.sixuan-candidates .candidate-popup-text {
    padding: 2px 10px 0;
    color: #3DFF8C;
    font-family: "Ubuntu Sans Mono", monospace;
    font-size: 12px;
}

.sixuan-candidates .candidate-box {
    padding: 7px 14px;
    spacing: 6px;
    border-radius: 16px;
    background-color: transparent;
    color: #E8F0EA;
    border-width: 0;
    box-shadow: none;
}

.sixuan-candidates .candidate-box:hover {
    background-color: rgba(255, 255, 255, 0.07);
    color: #E8F0EA;
}

.sixuan-candidates .candidate-box:selected {
    background-color: #3DFF8C;
    background-gradient-start: #6BFFAA;
    background-gradient-end: #22E07A;
    background-gradient-direction: vertical;
    color: #06210F;
    font-weight: bold;
    box-shadow: 0 0 14px 0 rgba(61, 255, 140, 0.40);
}

.sixuan-candidates .candidate-index {
    padding: 0;
    color: #66726C;
    font-family: "Ubuntu Sans Mono", monospace;
    font-size: 11px;
}

.sixuan-candidates .candidate-box:selected .candidate-index {
    color: rgba(6, 33, 15, 0.6);
}

.sixuan-candidates .candidate-page-button-box {
    spacing: 4px;
    padding: 4px;
}

.sixuan-candidates .candidate-page-button {
    width: 28px;
    height: 28px;
    min-width: 28px;
    min-height: 28px;
    padding: 0;
    border: 1px solid rgba(255, 255, 255, 0.06);
    border-radius: 999px;
    color: #9AA7A0;
    background-color: #1A1F23;
    background-gradient-start: #232A2E;
    background-gradient-end: #121618;
    background-gradient-direction: vertical;
    box-shadow: 3px 3px 6px 0 rgba(0, 0, 0, 0.55);
}

.sixuan-candidates .candidate-page-button:hover {
    color: #E8F0EA;
    background-gradient-start: #303A3F;
    background-gradient-end: #1A1F23;
}

.sixuan-candidates .candidate-page-button:active {
    box-shadow: inset 2px 2px 4px 0 rgba(0, 0, 0, 0.6);
}

.sixuan-candidates .candidate-page-button:insensitive {
    color: rgba(154, 167, 160, 0.35);
    box-shadow: none;
}

.sixuan-candidates .candidate-page-button StIcon {
    icon-size: 12px;
}
